def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp_bids = []
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > budget:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                    urgent_opp_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_prev = max(urgent_opp_bids) if urgent_opp_bids else highest_prev

    tight_supply = supply <= 17
    ample_supply = supply >= 22
    critical_me = (no_water_days >= 2) or (hp <= 3)
    pressured_me = (no_water_days >= 1) or (hp <= 5)

    if critical_me:
        bid = max(urgent_prev + 2.5, DAILY_SALARY * 0.95)
        if budget < bid:
            bid = budget
        return float(max(0.0, min(budget, bid)))

    if tight_supply:
        if highest_prev >= 120:
            bid = 36.0 if hp >= 7 and no_water_days == 0 else 78.0
        else:
            bid = max(52.0, urgent_prev + 1.8)
            if pressured_me:
                bid = max(bid, 74.0)
        return float(max(0.0, min(budget, bid)))

    if ample_supply:
        if pressured_me:
            bid = max(34.0, min(62.0, highest_prev * 0.72 + 2.0))
        else:
            bid = 16.0 if highest_prev > 90 else 22.0
        return float(max(0.0, min(budget, bid)))

    if pressured_me:
        bid = max(48.0, min(88.0, urgent_prev + 1.2))
    else:
        if highest_prev > 140:
            bid = 24.0
        elif highest_prev > 80:
            bid = 31.0
        else:
            bid = max(26.0, highest_prev * 0.6 + 3.0)

    if rich_count >= 2 and not pressured_me:
        bid *= 0.9

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if budget <= 0:
        return 0.0

    # Collect yesterday bids only from immediate previous_trace
    prev_bids = []
    prev_info = []
    for opp_id, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                continue
            prev_bids.append(b)
            prev_info.append((opp_id, b, prev.get('hp_after', None), prev.get('status', None)))

    # Baseline target: aim slightly above Eric-like pressure but far below Cindy-like extremes
    # Use supply to cap intensity: more supply -> can bid less while still securing water.
    # Approximate expected number of water units available.
    # Ensure indices are ints where needed.
    supply_units = int(supply / WATER_REQ) if WATER_REQ > 0 else 0
    if supply_units < 1:
        supply_units = 1

    # Determine yesterday pressure bands
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        lowest_prev_bid = min(prev_bids)
        # If Cindy-like high pressure exists, avoid matching it.
        high_band = 0.75 * highest_prev_bid
        mid_target = max(DAILY_SALARY * 0.55, lowest_prev_bid + 20.0)

        # If someone died yesterday, they likely over/under bid; use their direction to infer aggressiveness.
        # If any opponent had negative hp_after, treat as "failed" and bid moderately (not extreme).
        failed = False
        for _, b, hp_after, status in prev_info:
            if hp_after is not None:
                try:
                    if float(hp_after) < 0:
                        failed = True
                        break
                except Exception:
                    pass

        # Core bid decision
        if failed:
            target = min(mid_target, DAILY_SALARY * 0.75)
        else:
            # If nobody died, bid closer to the top but still avoid Cindy extremes.
            target = min(max(mid_target, DAILY_SALARY * 0.65), DAILY_SALARY * 0.85)

        # If yesterday highest bid was extremely high, we assume Cindy is pushing; reduce.
        if highest_prev_bid >= DAILY_SALARY * 1.5:
            target = min(target, DAILY_SALARY * 0.70)

        # If our hp is low, we must secure water: increase toward target+.
        if hp <= 2.0 or no_water_days >= 2:
            target = max(target, DAILY_SALARY * 0.85)
        elif hp <= 4.0:
            target = max(target, DAILY_SALARY * 0.70)

        # If supply is high, we can bid slightly less.
        if supply >= 22.0:
            target *= 0.95
        elif supply <= 16.0:
            target *= 1.05

    else:
        # No previous bids: use conservative mid bid.
        target = DAILY_SALARY * 0.60
        if hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * 0.90
        elif hp <= 4.0:
            target = DAILY_SALARY * 0.75

    # Convert target to a feasible bid with budget and some safety margin.
    # Also avoid bidding above budget.
    bid = float(target)

    # Small day-based modulation to prevent ties/predictability.
    # Use day parity only.
    if int(day) % 2 == 0:
        bid *= 1.02
    else:
        bid *= 0.98

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget

    # Ensure we don't bid trivially low when we need water.
    if (hp <= 2.0 or no_water_days >= 2) and bid < DAILY_SALARY * 0.6:
        bid = min(budget, DAILY_SALARY * 0.85)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # First day: no trace, bid moderate
    if day == 1 or not any(opp.get('previous_trace', {}).get('bid') is not None for opp in alive_opponents):
        base_bid = min(budget, DAILY_SALARY * 0.6)
        if hp <= 3:
            base_bid = min(budget, DAILY_SALARY * 0.85)
        return max(1, base_bid)

    # Collect yesterday's bids
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    if not prev_bids:
        # fallback
        base = min(budget, DAILY_SALARY * 0.6)
        if hp <= 3:
            base = min(budget, DAILY_SALARY * 0.85)
        return max(1, base)

    max_prev = max(prev_bids)
    avg_prev = sum(prev_bids) / len(prev_bids)

    # Determine bid
    if hp <= 2:
        # desperate: bid high but not over budget
        target = max(DAILY_SALARY * 0.9, max_prev + 1.5)
        return min(budget, target)
    elif hp <= 4:
        target = min(max_prev * 1.2, DAILY_SALARY * 0.85)
        return min(budget, target)
    else:
        # healthy: try to match or slightly beat yesterday's max
        # but don't overspend
        if max_prev >= DAILY_SALARY * 0.8:
            # high competition, stay moderate to preserve budget
            target = min(budget, DAILY_SALARY * 0.65)
        else:
            target = min(budget, max_prev + 1.0)
        return max(1, target)
